import math

def f(s,m,p):
 assert all(a%b==0 for a,b in zip(m,p))
 r=max(s[0]/m[0],s[1]/m[1])
 o=tuple(int(math.ceil(d/r)) for d in s) if r>1 else s
 return tuple((d+q-1)//q*q for d,q in zip(o,p))
for s in [(1000,500),(101,51),(224,224),(1,1000)]:
 print(s, f(s,(224,224),(16,16)))
n=0
for x in range(1,301):
 for y in range(1,301):
  o=f((x,y),(224,192),(16,32))
  assert 0<o[0]<=224 and 0<o[1]<=192 and o[0]%16==0 and o[1]%32==0
  n+=1
print('bounded positive-integer cases:',n)
